import React, { useEffect, useState } from 'react';
import { Box, Typography, Container } from '@mui/material';

// Today's Ayah of the Day, the same one the app shows (backend 133b).
// The ayah comes from /v1/daily-ayah; its text from a bundled copy of the curated list.
const API = 'https://node-api.imuslimlife.com/v1/daily-ayah';
const DIR = '/assets/app/daily-ayah';
const BGS = [3, 8, 14, 21, 27, 33, 40, 45];
const C = { gold: '#E2C15A', gold2: '#F3DC8E', ivory: '#F7F1E3', mist: '#C9CEE0', night: '#0B1130' };
const SERIF = '"Marcellus", "Amiri", Georgia, serif';

const plural = (n, one, many) => `${n.toLocaleString()} ${n === 1 ? one : many}`;

export const DailyAyahPreview = () => {
    const [day, setDay] = useState(null);

    useEffect(() => {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 8000);
        Promise.all([
            fetch(API, { signal: ctrl.signal }).then((r) => (r.ok ? r.json() : Promise.reject(r.status))),
            fetch(`${DIR}/ayahs.json`, { signal: ctrl.signal }).then((r) => r.json()),
        ])
            .then(([today, texts]) => {
                const text = texts[today.ayah.id];
                if (text) setDay({ ...today, text });
            })
            .catch(() => {}) // No ayah, no section: the page reads fine without it.
            .finally(() => clearTimeout(timer));
        return () => { clearTimeout(timer); ctrl.abort(); };
    }, []);

    if (!day) return null;
    const n = parseInt(day.date.replace(/-/g, ''), 10);
    const bg = `${DIR}/bg${BGS[n % BGS.length]}.jpg`;
    const long = day.text.a.length > 380;

    return (
        <Box component="section" id="ayah-of-the-day" sx={{ bgcolor: C.night, py: { xs: 8, md: 10 } }}>
            <Container maxWidth="md">
                <Box sx={{
                    position: 'relative', overflow: 'hidden', borderRadius: '28px', px: { xs: 3, sm: 6 }, py: { xs: 5, sm: 7 },
                    textAlign: 'center', color: C.ivory,
                    backgroundImage: `linear-gradient(180deg, rgba(5,8,25,.62), rgba(5,8,25,.8)), url(${bg})`,
                    backgroundSize: 'cover', backgroundPosition: 'center',
                    boxShadow: 'inset 0 0 0 1px rgba(226,193,90,.45), 0 24px 60px rgba(0,0,0,.45)',
                    '&::before': { content: '""', position: 'absolute', inset: 10, borderRadius: '20px', border: '1px solid rgba(226,193,90,.22)', pointerEvents: 'none' },
                }}>
                    <Typography sx={{ fontSize: 13, fontWeight: 600, letterSpacing: '.22em', textTransform: 'uppercase', color: C.gold }}>
                        Ayah of the Day
                    </Typography>
                    <Typography sx={{ fontSize: 14, color: C.mist, mt: 0.8 }}>Today’s ayah for the whole Ummah</Typography>
                    <Typography dir="rtl" lang="ar" sx={{
                        fontFamily: '"Amiri Quran", "Amiri", serif', fontSize: { xs: long ? 22 : 28, sm: long ? 26 : 36 },
                        lineHeight: 2.1, mt: 3, mb: 2,
                    }}>{day.text.a}</Typography>
                    <Typography sx={{ fontSize: { xs: 15, sm: 17 }, color: C.mist, lineHeight: 1.7, maxWidth: 620, mx: 'auto' }}>
                        {day.text.e}
                    </Typography>
                    <Typography sx={{ fontFamily: SERIF, fontSize: 17, color: C.gold2, mt: 2.5 }}>{day.text.r}</Typography>
                    {(day.likes > 0 || day.shares > 0) && (
                        <Typography sx={{ fontSize: 13.5, color: C.mist, mt: 2 }}>
                            {[day.likes > 0 && `♥ Liked by ${plural(day.likes, 'person', 'people')}`,
                                day.shares > 0 && `Shared ${plural(day.shares, 'time', 'times')}`].filter(Boolean).join('  ·  ')}
                        </Typography>
                    )}
                    <Typography sx={{ fontSize: 13, color: C.mist, mt: 3, opacity: 0.85 }}>
                        Like, listen and share it in the Salat-e-Mustaqeem app. English: Sahih International.
                    </Typography>
                </Box>
            </Container>
        </Box>
    );
};
